"""Regenerate crates/markitdown-core/src/docx/dingbats.rs from mammoth's table.

usage: uv run --project oracle python scripts/gen_dingbats.py
"""
from pathlib import Path

from mammoth.docx.dingbats import dingbats

out = Path(__file__).resolve().parent.parent / "crates/markitdown-core/src/docx/dingbats.rs"
rows = sorted(dingbats.items())
lines = [
    "//! `w:sym` (font, char) -> Unicode, generated by scripts/gen_dingbats.py from",
    "//! mammoth 1.11.0 (BSD-2-Clause), which takes it from dingbat-to-unicode.",
    "",
    "/// Sorted by (font, code) for binary search.",
    "#[rustfmt::skip]",
    "pub static DINGBATS: &[(&str, u32, u32)] = &[",
]
entries = [f'("{font}", {code}, {cp}),' for (font, code), cp in rows]
lines += ["    " + " ".join(entries[i : i + 6]) for i in range(0, len(entries), 6)]
lines += ["];", ""]
out.write_text("\n".join(lines))
print(f"wrote {len(rows)} entries to {out}")
